  + '};\n'
  + '\n'
  + 'type PopoverStoreActions = {\n'
  + '  toggle: () => void;\n'
  + '  open: () => void;\n'
  + '  close: () => void;\n'
  + '\n'
  + '  setFloatingStyles: (floatingStyles: CSSProperties) => void;\n'
  + '  setElRef: (el: Element | null) => void;\n'
  + '  setFloatingRef: (el: HTMLElement | null) => void;\n'
  + '\n'
  + '  disableTriggerClickHandler: () => void;\n'
  + '  enableTriggerClickHandler: () => void;\n'
  + '};\n'
  + '\n'
  + 'type PopoverStore = PopoverStoreState & PopoverStoreActions;\n'
  + '\n'
  + 'type BuildPopoverStoreArgs = {\n'
